#!/usr/bin/env bash
# Create the buckets (`aws-s3`, environment `hybrid`). Generated by trestle; re-render to update.
set -euo pipefail
cd "$(dirname "$0")/.."

# Secrets kept in secrets.env (git-ignored) are read like exported ones.
if [ -f secrets.env ]; then
  set -a
  # shellcheck source=/dev/null
  . ./secrets.env
  set +a
fi

# save_secret NAME VALUE: record NAME in secrets.env (and this shell), unless secrets.env
# already sets it.
save_secret() {
  if [ -f secrets.env ] && grep -q "^$1=" secrets.env; then
    echo "secrets.env already sets $1; leaving it as is"
  else
    (umask 077 && printf '%s=%s\n' "$1" "$2" >> secrets.env)
    echo "saved $1 to secrets.env"
  fi
  export "$1=$2"
}

region='us-east-1'
endpoint=()
for bucket in 'unity' 'mlflow' ; do
  if aws s3api head-bucket --bucket "$bucket" ${endpoint[@]+"${endpoint[@]}"} 2>/dev/null; then
    echo "bucket $bucket exists"
  elif [ "$region" = us-east-1 ]; then
    aws s3api create-bucket --bucket "$bucket" --region "$region" \
      ${endpoint[@]+"${endpoint[@]}"} >/dev/null
    echo "created bucket $bucket"
  else
    aws s3api create-bucket --bucket "$bucket" --region "$region" \
      --create-bucket-configuration "LocationConstraint=$region" \
      ${endpoint[@]+"${endpoint[@]}"} >/dev/null
    echo "created bucket $bucket"
  fi
done

# An access key for the stack, scoped to these buckets.
key_var='AWS_ACCESS_KEY_ID'
secret_var='AWS_SECRET_ACCESS_KEY'
if [ -n "${!key_var:-}" ]; then
  echo "$key_var is set; the stack uses that key"
else
  user='trestle-hybrid'
  aws iam get-user --user-name "$user" >/dev/null 2>&1 \
    || aws iam create-user --user-name "$user" >/dev/null
  aws iam put-user-policy --user-name "$user" --policy-name trestle-buckets --policy-document '{
    "Version": "2012-10-17",
    "Statement": [
      {"Effect": "Allow", "Action": "s3:*", "Resource": ["arn:aws:s3:::unity", "arn:aws:s3:::unity/*", "arn:aws:s3:::mlflow", "arn:aws:s3:::mlflow/*"]}
    ]
  }'
  read -r key secret < <(aws iam create-access-key --user-name "$user" \
    --query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text)
  save_secret "$key_var" "$key"
  save_secret "$secret_var" "$secret"
fi
